def shortest_path(graph, source, target):
    # Initialize the distance and path arrays with infinity and None respectively
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    path = {node: None for node in graph}

    # Queue for BFS: (current node, current path)
    queue = [(source, [source])]

    while queue:
        node, path = queue.pop(0)

        # If we reached the target, reconstruct the path and break
        if node == target:
            path_nodes = path[:]
            path_nodes.reverse()
            return (distances[target], path_nodes)

        # Explore neighbors
        for neighbor, weight in graph[node]:
            new_distance = distances[node] + weight
            if new_distance < distances[neighbor]:
                distances[neighbor] = new_distance
                path[neighbor] = path[node]
                queue.append((neighbor, path[:]+[neighbor]))

    # If we exhaust the queue without finding the target, return infinity and None
    return (float('inf'), None)

