def shortest_path(graph, source, target):
    # Initialize the distance array where the distance to the source is 0 and to all others is inf
    distances = {node: float("inf") for node in graph}
    distances[source] = 0
    # Initialize the path array to store the path components
    path = {node: None for node in graph}

    # Priority queue to hold nodes to be processed, initially just the source node
    from collections import defaultdict
    priority_queue = [(0, source)]  # (distance, node)

    while priority_queue:
        current_distance, current_node = heappop(priority_queue)

        # If we found the target, reconstruct the path
        if current_node == target:
            path_reversed = []
            while current_node is not None:
                path_reversed.append(current_node)
                current_node = path[current_node]
            return (current_distance, path_reversed[::-1])

        # Skip if we've already found a shorter path to this node
        if current_distance > distances[current_node]:
            continue

        # Explore neighbors
        for neighbor, weight in graph.get(current_node, ()):
            distance = current_distance + weight

            # If a shorter path is found, update the distance and recompute the path
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                path[neighbor] = current_node
                heappush(priority_queue, (distance, neighbor))

    # If we exit the loop without finding the target, it's unreachable
    return (float("inf"), None)

