def shortest_path(graph, source, target):
    # Initialize distances to all nodes as infinity except for the source node which is 0.
    distances = {node: float("inf") for node in graph}
    distances[source] = 0
    # Initialize a dictionary to keep track of the predecessor of each node for the path reconstruction.
    predecessors = {node: None for node in graph}

    # Priority queue to get the node with the smallest distance next.
    priority_queue = [(0, source)]

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        # If we reached the target node, reconstruct the path.
        if current_node == target:
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = predecessors[current_node]
            path.reverse()
            return (current_distance, path)

        # Explore the neighbors.
        for neighbor, weight in graph.get(current_node, []):
            distance = current_distance + weight

            # Only consider the path if it's shorter than the previously recorded distance.
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                predecessors[neighbor] = current_node
                heapq.heappush(priority_queue, (distance, neighbor))

    # If target node is unreachable, return infinity and None.
    return (float("inf"), None)

# Helper function to use with the priority queue.
