def shortest_path(graph, source, target):
    # Initialize distances
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    # Initialize the queue for BFS
    queue = [source]
    visited = set()

    while queue:
        current = queue.pop(0)
        visited.add(current)

        for neighbour, weight in graph[current]:
            if neighbour in visited:
                continue
            distance_through_current = distances[current] + weight
            if distance_through_current < distances[neighbour]:
                distances[neighbour] = distance_through_current
                # Add the neighbour to the queue with its distance from the source
                queue.append(neighbour)

    # If target is not reachable, distances[target] will be infinity
    if distances[target] == float('inf'):
        return float("inf"), None
    else:
        # Reconstruct the path from distances
        path = []
        current = target
        while current != source:
            path.append(current)
            for neighbour, weight in graph[current]:
                if distances[neighbour] == distances[current] - weight:
                    current = neighbour
                    break
        path.append(source)  # Add the source to the path
        path.reverse()  # Reverse the path to start from source to target
        return distances[target], path
