    # Initialize the distances to all nodes as infinity except for the source node which is 0
    distances = {node: float("inf") for node in graph}
    distances[source] = 0

    # Initialize the predecessors for each node
    predecessors = {node: None for node in graph}

    # Priority queue to hold the nodes to be visited, initialized with the source node
    from heapq import heappush, heappop
    pq = [(0, source)]

    while pq:
        # Pop the node with the smallest distance
        current_distance, current_node = heappop(pq)

        # If we reached the target, reconstruct the path and return the distances and path
        if current_node == target:
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = predecessors[current_node]
            return (current_distance, path[::-1])

        # If we are already having a better (smaller) distance to the current_node, skip it
        if current_distance > distances[current_node]:
            continue

        # Explore the neighbors
        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            # Only if the new distance is smaller, update the distance and the predecessor
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                predecessors[neighbor] = current_node
                # Add the neighbor to the priority queue
                heappush(pq, (distance, neighbor))

    # If the target is not reachable, return infinity and None
