def shortest_path(graph, source, target):
    # Initialize the distances and the predecessor nodes.
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    # Initialize the path to all nodes as None.
    path = {node: None for node in graph}

    # Set up the priority queue (we use a dictionary as a min-heap).
    priority_queue = {node: 0 for node in graph}

    # Priority queue is initialized with the source node.
    from collections import deque
    priority_queue[source] = 0
    path[source] = source
    heap = deque(sorted(priority_queue.items(), key=lambda item: item[1]))

    # Run the Dijkstra's algorithm.
    while heap:
        current_node, current_distance = heap.popleft()
        if current_distance > distances[current_node]:
            continue
        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                path[neighbor] = current_node
                heap.append((neighbor, distance))
                heap.remove((neighbor, distance)) # Remove the entry to maintain the heap property
                heap.sort(key=lambda node_dist: node_dist[1]) # Re-sort the heap

    # If no path is found, distances[target] will remain infinity.
    if distances[target] == float('inf'):
        return (float('inf'), None)
    else:
        # Reconstruct the path from target to source.
        result_path = []
        node = target
        while node is not None:
            result_path.append(node)
            node = path[node]
        result_path.reverse()
        return (distances[target], result_path)
