            return float("inf"), None

        visited = set()
        queue = [(source, [source])]

        while queue:
            current, path = queue.pop(0)
            visited.add(current)

            for neighbor in graph[current]:
                if neighbor not in visited:
                    if neighbor == target:
                        return len(path), path + [neighbor]
                    queue.append((neighbor, path + [neighbor]))

