from collections import deque

def shortest_path(graph, source, target):
    # Initialize distances dictionary to store the shortest distance from source to every node
    distances = {node: float("inf") for node in graph}
    distances[source] = 0
    # Initialize the queue with the source node
    queue = deque([(source, [source])])

    while queue:
        current_node, path = queue.popleft()
        for neighbor, weight in graph[current_node]:
            distance = distances[current_node] + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                queue.append((neighbor, path + [neighbor]))
                # If we reached the target node, return distance and path
                if neighbor == target:
                    return (distance, path)

    # If target node is unreachable, return infinity and None
    return (float("inf"), None)

# Example usage:
graph = {
    'A': [('B', 1), ('C', 4)],
    'B': [('A', 1), ('C', 2), ('D', 5)],
    'C': [('A', 4), ('B', 2), ('D', 1)],
    'D': [('B', 5), ('C', 1)]
}

source = 'A'
target = 'D'
distance, path = shortest_path(graph, source, target)
print(f"Shortest path from {source} to {target} is {distance} with path {path}")
